"""Legacy-compatible CRMScript numeric division."""

from typing import Final

_DIV_ZERO_AUDIT: Final[str] = "SCRIPT_DIV0"


def _coerce_numeric(value: object) -> float:
    """Apply legacy numeric coercion for supported operand values."""
    if value is None or value == "":
        return 0.0

    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        # Unsupported or missing values behave as zero in numeric context.
        return 0.0


def safe_div(a: object, b: object) -> tuple[float, list[str]]:
    """Divide using the legacy CRMScript division-by-zero behavior."""
    numerator = _coerce_numeric(a)
    divisor = _coerce_numeric(b)

    if divisor == 0.0:
        return 0.0, [_DIV_ZERO_AUDIT]

    return float(numerator / divisor), []
